package com.example.jobpuzzle.analysis.controller;
import com.example.jobpuzzle.analysis.rag.service.AnalysisVectorIndexService;import com.example.jobpuzzle.analysis.service.AnalysisCaseService;import com.example.jobpuzzle.global.error.*;import com.example.jobpuzzle.global.security.CustomUserDetails;import com.example.jobpuzzle.user.entity.User;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(AnalysisCaseController.class) class AnalysisCaseIndexControllerTest { @Autowired MockMvc mvc; @MockBean AnalysisCaseService cases; @MockBean AnalysisVectorIndexService index; @Test void indexesOwnedCase()throws Exception{mvc.perform(post("/analysis-cases/31/index").with(user(principal())).with(csrf())).andExpect(status().isOk()).andExpect(jsonPath("$.success").value(true));verify(index).index(17L,31L);} @Test void preservesIndexNotReady()throws Exception{doThrow(new CustomException(ErrorCode.VECTOR_INDEX_NOT_READY)).when(index).index(17L,31L);mvc.perform(post("/analysis-cases/31/index").with(user(principal())).with(csrf())).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("ANALYSIS_011"));} private CustomUserDetails principal(){User u=User.builder().build();ReflectionTestUtils.setField(u,"userId",17L);return new CustomUserDetails(u);} }
